svg.script:
{
  "diagramType": "Event-Driven Architecture",
  "projectName": "Food Delivery System",
  "description": "Asynchronous event-based communication architecture",
  "event_sources": [
    {"id": "evt1", "name": "Order Placed", "type": "domain_event", "position": {"x": 150, "y": 300}},
    {"id": "evt2", "name": "Restaurant Accepted", "type": "domain_event", "position": {"x": 150, "y": 450}},
    {"id": "evt3", "name": "Delivery Started", "type": "domain_event", "position": {"x": 150, "y": 600}}
  ],
  "event_bus": {"id": "bus", "name": "Event Bus", "type": "kafka", "position": {"x": 700, "y": 450}},
  "event_consumers": [
    {"id": "cons1", "name": "Notification Service", "subscribes_to": ["evt1", "evt2", "evt3"], "position": {"x": 1300, "y": 300}},
    {"id": "cons2", "name": "Analytics Service", "subscribes_to": ["evt1", "evt2", "evt3"], "position": {"x": 1300, "y": 450}},
    {"id": "cons3", "name": "Inventory Service", "subscribes_to": ["evt1"], "position": {"x": 1300, "y": 600}}
  ],
  "designTokens": {"lightMode": {"canvas": "#FFFFFF"}, "darkMode": {"canvas": "#0D0D0D"}}
}
